package love.onlyyours;
import android.content.*;
import android.security.keystore.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import java.security.KeyStore;
import java.util.concurrent.*;
import org.json.JSONObject;

/** Background routing credential only. Never stores vault keys or message content. */
public final class PushRegistration {
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();
 private static final String ALIAS="onlyyours-push-routing-v1",ORIGIN="https://only-yours-app-private.vercel.app";
 private static javax.crypto.SecretKey key() throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)ks.getKey(ALIAS,null);}
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("onlyyours-push",0);}
 private static synchronized JSONObject read(Context c){try{String box=prefs(c).getString("sealed","");if(box.isEmpty())return new JSONObject();byte[] raw=android.util.Base64.decode(box,android.util.Base64.NO_WRAP);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(raw,0,12)));return new JSONObject(new String(cipher.doFinal(java.util.Arrays.copyOfRange(raw,12,raw.length)),java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){return new JSONObject();}}
 private static synchronized void update(Context c,String name,Object value){try{JSONObject state=read(c);state.put(name,value);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] iv=cipher.getIV(),body=cipher.doFinal(state.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),all=new byte[iv.length+body.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(body,0,all,iv.length,body.length);prefs(c).edit().putString("sealed",android.util.Base64.encodeToString(all,android.util.Base64.NO_WRAP)).commit();}catch(Exception ignored){prefs(c).edit().putString("status","storage-unavailable").apply();}}
 public static JSONObject post(String path,String session,JSONObject body)throws Exception{java.net.HttpURLConnection h=(java.net.HttpURLConnection)new java.net.URL(ORIGIN+"/api/"+path).openConnection();h.setRequestMethod("POST");h.setConnectTimeout(8000);h.setReadTimeout(8000);h.setRequestProperty("Authorization","Bearer "+session);h.setRequestProperty("Content-Type","application/json");h.setDoOutput(true);try(java.io.OutputStream out=h.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}try{int status=h.getResponseCode();if(status!=200)throw new java.io.IOException("Service status "+status);try(java.io.InputStream in=h.getInputStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1){out.write(bytes,0,n);if(out.size()>16000)throw new java.io.IOException("Invalid response");}return new JSONObject(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));}}finally{h.disconnect();}}
 public static void start(Context c){Context app=c.getApplicationContext();if(!c.getSharedPreferences("MainActivity",0).getBoolean("alerts",false))return;try{com.google.firebase.messaging.FirebaseMessaging.getInstance().setAutoInitEnabled(true);com.google.firebase.messaging.FirebaseMessaging.getInstance().getToken().addOnSuccessListener(t->token(app,t)).addOnFailureListener(e->prefs(app).edit().putString("status","token-unavailable").apply());}catch(Exception e){prefs(app).edit().putString("status","play-services-unavailable").apply();}}
 public static void session(Context c,String session){if(session==null||!session.matches("[a-f0-9]{48}"))return;update(c,"session",session);start(c);}
 public static void pair(Context c,String partner,long epoch){update(c,"partner",partner==null?"":partner);update(c,"epoch",epoch);}
 public static void token(Context c,String token){update(c,"token",token);register(c);}
 private static void register(Context c){worker.execute(()->{try{if(!c.getSharedPreferences("MainActivity",0).getBoolean("alerts",false))return;JSONObject s=read(c);if(s.optString("session").isEmpty()||s.optString("token").isEmpty())return;String id=prefs(c).getString("installation","");if(id.isEmpty()){id=java.util.UUID.randomUUID().toString();prefs(c).edit().putString("installation",id).commit();}JSONObject response=post("push/register",s.getString("session"),new JSONObject().put("installation",id).put("token",s.getString("token")));prefs(c).edit().putString("status",response.optBoolean("configured")?"ready":"server-setup-pending").apply();}catch(Exception e){prefs(c).edit().putString("status","registration-pending").apply();}});}
 public static String status(Context c){return prefs(c).getString("status","not-enabled");}
 public static void forget(Context c){try{com.google.firebase.messaging.FirebaseMessaging.getInstance().setAutoInitEnabled(false);}catch(Exception ignored){}JSONObject before=read(c);String id=prefs(c).getString("installation","");prefs(c).edit().remove("sealed").putString("status","not-enabled").commit();worker.execute(()->{try{post("push/unregister",before.optString("session"),new JSONObject().put("installation",id));}catch(Exception ignored){}});}
 public static boolean verify(Context c,java.util.Map<String,String> data){try{if(!c.getSharedPreferences("MainActivity",0).getBoolean("alerts",false))return false;JSONObject s=read(c);String partner=data.get("partner");long epoch=Long.parseLong(data.get("epoch"));if(partner==null||!partner.equals(s.optString("partner"))||epoch!=s.optLong("epoch",-1))return false;post("push/verify",s.getString("session"),new JSONObject().put("partner",partner).put("epoch",epoch));return true;}catch(Exception e){return false;}}
}
